UPDATE ORDERS
SET TOTAL_PRICE = GREATEST( 0, NVL(PRODUCT_AMOUNT, 0) - NVL(INSTANT_DISCOUNT, 0) - NVL(COUPON_DISCOUNT, 0) - NVL(CASH_USED, 0) + NVL(DELIVERY_FEE, 0) )
WHERE ORDER_NO = #{orderNo}

UPDATE ORDERS

SET ORDER_STATUS = #{orderStatus}

WHERE ORDER_NO = #{orderNo}

UPDATE ORDERS

SET ORDER_ADDRESS_NO = #{addressNo}

WHERE ORDER_NO = #{orderNo}
